  // ============================================
  // PROPIEDADES NUEVAS PARA COTIZACIONES
  // ============================================
  
  guardandoCotizacion: boolean = false;
  cotizacionGuardada: boolean = false;
  errorGuardando: boolean = false;
  cotizacionId: string = '';
  
  // Timer para guardar automáticamente después de cambios
  private autoSaveTimer: any;

  // ============================================
  // CONSTRUCTOR
  // ============================================
  
  constructor(
    private router: Router,
    private cotizacionService: CotizacionService
  ) {}

  // ============================================
  // LIFECYCLE HOOKS
  // ============================================
  
  ngOnInit(): void {
    // Inicialización si es necesaria
  }

  ngOnDestroy(): void {
    // Limpiar timer si existe
    if (this.autoSaveTimer) {
      clearTimeout(this.autoSaveTimer);
    }
  }

  // ============================================
  // MÉTODOS DE VEHÍCULOS
  // ============================================
  
  selectVehicle(vehicle: Vehicle): void {
    this.currentVehicle = vehicle;
    this.currentVehicleAngle = 'front';
  }

  rotateVehicle(direction: 'left' | 'right'): void {
    const angles = ['front', 'side', 'back', 'top'];
    const currentIndex = angles.indexOf(this.currentVehicleAngle);
    
    if (direction === 'right') {
      this.currentVehicleAngle = angles[(currentIndex + 1) % angles.length];
    } else {
      this.currentVehicleAngle = angles[(currentIndex - 1 + angles.length) % angles.length];
    }
  }

  getCurrentVehicleImage(): string {
    if (!this.currentVehicle) return '';
    return this.currentVehicle.imageAngles[this.currentVehicleAngle as keyof typeof this.currentVehicle.imageAngles];
  }

  addVehicle(): void {
    if (!this.currentVehicle) return;

    const existingVehicle = this.selectedVehicles.find(
      sv => sv.vehicle.id === this.currentVehicle!.id
    );

    if (existingVehicle) {
      existingVehicle.quantity++;
      existingVehicle.uniformAssignments.push({
        vehicleIndex: existingVehicle.quantity,
        uniformId: 'casual' // Default
      });
    } else {
      this.selectedVehicles.push({
        vehicle: this.currentVehicle,
        quantity: 1,
        uniformAssignments: [{
          vehicleIndex: 1,
          uniformId: 'casual' // Default
        }]
      });
    }

    // Guardar automáticamente después de agregar vehículo
    this.scheduleAutoSave();
  }

  removeVehicle(selectedVehicle: SelectedVehicle): void {
    const index = this.selectedVehicles.indexOf(selectedVehicle);
    if (index > -1) {
      this.selectedVehicles.splice(index, 1);
    }
    
    // Guardar automáticamente después de remover
    this.scheduleAutoSave();
  }

  getTotalVehicles(): number {
    return this.selectedVehicles.reduce((total, sv) => total + sv.quantity, 0);
  }

  // ============================================
  // MÉTODOS DE UNIFORMES
  // ============================================
  
  selectUniform(uniform: Uniform): void {
    this.currentUniform = uniform;
    this.currentUniformAngle = 'front';
  }

  rotateUniform(direction: 'left' | 'right'): void {
    const angles = ['front', 'side', 'back', 'top'];
    const currentIndex = angles.indexOf(this.currentUniformAngle);
    
    if (direction === 'right') {
      this.currentUniformAngle = angles[(currentIndex + 1) % angles.length];
    } else {
      this.currentUniformAngle = angles[(currentIndex - 1 + angles.length) % angles.length];
    }
  }

  getCurrentUniformImage(): string {
    if (!this.currentUniform) return '';
    return this.currentUniform.imageAngles[this.currentUniformAngle as keyof typeof this.currentUniform.imageAngles];
  }

  openUniformSelector(vehicleId: string, index: number): void {
    this.selectedUniformForVehicle = { vehicleId, index };
  }

  assignUniform(uniformId: string): void {
    if (!this.selectedUniformForVehicle) return;

    const selectedVehicle = this.selectedVehicles.find(
      sv => sv.vehicle.id === this.selectedUniformForVehicle!.vehicleId
    );

    if (selectedVehicle) {
      const assignment = selectedVehicle.uniformAssignments.find(
        ua => ua.vehicleIndex === this.selectedUniformForVehicle!.index
      );

      if (assignment) {
        assignment.uniformId = uniformId;
      }
    }

    this.selectedUniformForVehicle = null;
    
    // Guardar automáticamente después de asignar uniforme
    this.scheduleAutoSave();
  }

  getUniformNameById(uniformId: string): string {
    const uniform = this.uniforms.find(u => u.id === uniformId);
    return uniform ? uniform.name : 'No asignado';
  }

  getUniformIcon(uniformId: string): string {
    const icons: { [key: string]: string } = {
      'camuflaje': '🎖️',
      'casual': '👔',
      'formal': '🤵'
    };
    return icons[uniformId] || '👤';
  }

  // ============================================
  // MÉTODOS DE EQUIPAMIENTO
  // ============================================
  
  toggleEquipment(equipment: Equipment): void {
    const index = this.selectedEquipment.findIndex(e => e.id === equipment.id);
    
    if (index > -1) {
      this.selectedEquipment.splice(index, 1);
    } else {
      this.selectedEquipment.push(equipment);
    }
    
    // Guardar automáticamente después de cambiar equipamiento
    this.scheduleAutoSave();
  }

  isEquipmentSelected(equipmentId: string): boolean {
    return this.selectedEquipment.some(e => e.id === equipmentId);
  }

  // ============================================
  // MÉTODOS DE COTIZACIÓN (NUEVOS)
  // ============================================
  
  /**
   * Programa un guardado automático después de 1 segundo
   * Si el usuario hace más cambios, reinicia el timer
   */
  private scheduleAutoSave(): void {
    // Limpiar timer anterior si existe
    if (this.autoSaveTimer) {
      clearTimeout(this.autoSaveTimer);
    }

    // Programar nuevo guardado
    this.autoSaveTimer = setTimeout(() => {
      this.guardarCotizacionAutomatica();
    }, 1000); // 1 segundo de debounce
  }

  /**
   * Guarda la cotización automáticamente en el backend
   */
  guardarCotizacionAutomatica(): void {
    // Si ya está guardando, no hacer nada
    if (this.guardandoCotizacion) return;
    
    // Si no hay vehículos seleccionados, no guardar
    if (this.selectedVehicles.length === 0) return;

    this.guardandoCotizacion = true;
    this.cotizacionGuardada = false;
    this.errorGuardando = false;

    // Preparar datos para enviar
    const cotizacionData: CotizacionData = {
      servicio: 'proteccion-ejecutiva',
      vehiculos: this.selectedVehicles.map(sv => ({
        tipo: sv.vehicle.id,
        cantidad: sv.quantity,
        unidades: sv.uniformAssignments.map(ua => ({
          numero: ua.vehicleIndex,
          uniforme: ua.uniformId
        }))
      })),
      uniformePrincipal: this.getMostUsedUniform(),
      equipamiento: this.equipment.map(eq => ({
        id: eq.id,
        nombre: eq.name,
        seleccionado: this.isEquipmentSelected(eq.id)
      }))
    };

    // Enviar al backend
    this.cotizacionService.guardarCotizacion(cotizacionData).subscribe({
      next: (response) => {
        this.guardandoCotizacion = false;
        this.cotizacionGuardada = true;
        this.errorGuardando = false;
        this.cotizacionId = response.cotizacionId || '';
        console.log('✅ Cotización guardada automáticamente:', response);
      },
      error: (error) => {
        this.guardandoCotizacion = false;
        this.cotizacionGuardada = false;
        this.errorGuardando = true;
        console.error('❌ Error al guardar cotización:', error);
        
        // Reintentar después de 5 segundos
        setTimeout(() => {
          this.guardarCotizacionAutomatica();
        }, 5000);
      }
    });
  }

  /**
   * Obtiene el uniforme más usado en la configuración
   */
  private getMostUsedUniform(): string {
    const uniformCounts: { [key: string]: number } = {};
    
    this.selectedVehicles.forEach(sv => {
      sv.uniformAssignments.forEach(ua => {
        uniformCounts[ua.uniformId] = (uniformCounts[ua.uniformId] || 0) + 1;
      });
    });

    let maxCount = 0;
    let mostUsedUniform = 'casual';
    
    Object.entries(uniformCounts).forEach(([uniformId, count]) => {
      if (count > maxCount) {
        maxCount = count;
        mostUsedUniform = uniformId;
      }
    });

    return mostUsedUniform;
  }

  /**
   * Navega al formulario de contacto con los datos de la cotización
   */
  solicitarCotizacion(): void {
    if (!this.cotizacionGuardada || !this.cotizacionId) {
      console.warn('⚠️ No hay cotización guardada para solicitar');
      return;
    }

    // Navegar al formulario de contacto con el ID de la cotización
    this.router.navigate(['/contacto'], {
      queryParams: {
        tipo: 'cotizacion',
        servicio: 'proteccion-ejecutiva',
        cotizacionId: this.cotizacionId
      }
    });
  }

  /**
   * Fuerza un guardado manual (por si el automático falla)
   */
  guardarManual(): void {
    this.guardarCotizacionAutomatica();
  }

  // ============================================
  // MÉTODOS DE NAVEGACIÓN
  // ============================================
  
  navigateTo(route: string): void {
    this.router.navigate([route]);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }

  scrollToSection(sectionId: string): void {
    const element = document.getElementById(sectionId);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }
